import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int M = scanner.nextInt();

        List<List<Integer>> divisorsList = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            divisorsList.add(new ArrayList<>());
        }

        for (int divisor = 2; divisor <= n; divisor++) {
            for (int multiple = 2 * divisor; multiple <= n; multiple += divisor) {
                divisorsList.get(multiple).add(divisor);
            }
        }

        long[] F = new long[n + 1];
        F[1] = 1;
        if (n >= 2) {
            F[2] = 2;
        }

        for (int i = 3; i <= n; i++) {
            F[i] = (2 * F[i - 1] + F[i / (i - 1)]) % M;
            long sumDiff = 0;
            for (int d : divisorsList.get(i)) {
                if (d >= 2 && d <= i - 2) {
                    sumDiff += F[i / d] - F[(i - 1) / d];
                }
            }
            F[i] = (F[i] + sumDiff) % M;
        }

        System.out.println(F[n] % M);
        scanner.close();
    }
}
